<template><div class="page"><el-tabs v-model="tab" class="tabs"><el-tab-pane label="习惯与健康" name="habit"><div class="toolbar"><el-button type="primary" @click="habitVisible=true">新建习惯</el-button></div><div class="habit-grid"><article v-for="x in habits" :key="x.id"><div><b>{{x.name}}</b><el-tag>{{x.frequency==='DAILY'?'每日':'每周'}}</el-tag></div><p><strong>{{x.streak}}</strong> 天连续 · 30 天完成率 {{x.completionRate30d}}%</p><el-progress :percentage="Number(x.completionRate30d)"/><div class="actions"><el-button type="success" @click="checkin(x)">今日打卡</el-button><el-button v-if="x.metric_type" @click="showTrend(x.metric_type)">查看趋势</el-button></div></article></div><el-card v-if="trend.points" shadow="never" class="trend"><h3>{{trend.metricType}} 趋势</h3><div v-for="p in trend.points" :key="p.checkin_date"><time>{{p.checkin_date}}</time><b>{{p.value}} {{p.unit}}</b></div></el-card></el-tab-pane><el-tab-pane label="联系人" name="contact"><div class="toolbar"><el-button type="primary" @click="contactVisible=true">新增联系人</el-button></div><el-table :data="contacts"><el-table-column prop="name" label="姓名"/><el-table-column prop="relationship" label="关系"/><el-table-column prop="company" label="公司"/><el-table-column prop="birthday" label="生日"/><el-table-column prop="last_contact_at" label="最近联系"/><el-table-column prop="follow_up_at" label="下次跟进"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="contacted(row)">标记已联系</el-button></template></el-table-column></el-table><div class="contact-cards"><article v-for="x in contacts" :key="x.id"><b>{{x.name}}</b><p>{{x.relationship||'未设置关系'}} · {{x.company||'未设置公司'}}</p><small>最近 {{x.last_contact_at||'无'}} · 跟进 {{x.follow_up_at||'无'}}</small><el-button @click="contacted(x)">已联系</el-button></article></div></el-tab-pane><el-tab-pane label="家庭资产" name="asset"><el-alert title="敏感详情在后端加密保存，列表不返回明文；查看时必须二次确认。" type="warning" show-icon :closable="false"/><div class="toolbar"><el-button type="primary" @click="assetVisible=true">新增资产</el-button></div><div class="asset-grid"><article v-for="x in assets" :key="x.id"><div><b>{{x.name}}</b><el-tag>{{x.asset_type}}</el-tag></div><p>位置：{{x.location||'-'}}</p><small>保修：{{x.warranty_until||'-'}} · 到期：{{x.expires_at||'-'}}</small><el-button v-if="x.sensitive" type="danger" plain @click="reveal(x)">二次确认查看敏感详情</el-button></article></div></el-tab-pane></el-tabs>
<el-dialog v-model="habitVisible" title="新建习惯/健康指标" width="min(540px,94vw)"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="habit.name"/></el-form-item><div class="two"><el-form-item label="频率"><el-select v-model="habit.frequency"><el-option label="每日" value="DAILY"/><el-option label="每周" value="WEEKLY"/></el-select></el-form-item><el-form-item label="指标"><el-select v-model="habit.metricType" clearable><el-option label="睡眠" value="SLEEP"/><el-option label="体重" value="WEIGHT"/><el-option label="运动" value="EXERCISE"/><el-option label="饮水" value="WATER"/></el-select></el-form-item></div><div class="two"><el-form-item label="目标值"><el-input-number v-model="habit.targetValue"/></el-form-item><el-form-item label="单位"><el-input v-model="habit.unit"/></el-form-item></div></el-form><template #footer><el-button type="primary" @click="createHabit">保存</el-button></template></el-dialog>
<el-dialog v-model="checkinVisible" title="习惯打卡" width="min(460px,92vw)"><el-form label-position="top"><el-form-item label="日期"><el-date-picker v-model="checkinForm.checkinDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="数值"><el-input-number v-model="checkinForm.value"/></el-form-item><el-form-item label="备注"><el-input v-model="checkinForm.note"/></el-form-item></el-form><template #footer><el-button type="primary" @click="saveCheckin">打卡</el-button></template></el-dialog>
<el-dialog v-model="contactVisible" title="新增联系人" width="min(560px,94vw)"><el-form label-position="top"><div class="two"><el-form-item label="姓名"><el-input v-model="contact.name"/></el-form-item><el-form-item label="关系"><el-input v-model="contact.relationship"/></el-form-item><el-form-item label="公司"><el-input v-model="contact.company"/></el-form-item><el-form-item label="生日"><el-date-picker v-model="contact.birthday" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="跟进时间"><el-date-picker v-model="contact.followUpAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item></div><el-form-item label="偏好"><el-input v-model="contact.preferences" type="textarea"/></el-form-item></el-form><template #footer><el-button type="primary" @click="createContact">保存</el-button></template></el-dialog>
<el-dialog v-model="assetVisible" title="新增家庭资产" width="min(580px,94vw)"><el-form label-position="top"><div class="two"><el-form-item label="类型"><el-select v-model="asset.assetType"><el-option v-for="x in assetTypes" :key="x" :value="x"/></el-select></el-form-item><el-form-item label="名称"><el-input v-model="asset.name"/></el-form-item><el-form-item label="购买金额"><el-input-number v-model="asset.purchaseAmount" :precision="2"/></el-form-item><el-form-item label="位置"><el-input v-model="asset.location"/></el-form-item><el-form-item label="保修截止"><el-date-picker v-model="asset.warrantyUntil" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="证件/合同/保单到期"><el-date-picker v-model="asset.expiresAt" type="date" value-format="YYYY-MM-DD"/></el-form-item></div><el-checkbox v-model="asset.sensitive">包含敏感信息</el-checkbox><el-form-item v-if="asset.sensitive" label="敏感详情（加密保存）"><el-input v-model="asset.sensitiveDetails" type="textarea"/></el-form-item><el-form-item label="备注"><el-input v-model="asset.note"/></el-form-item></el-form><template #footer><el-button type="primary" @click="createAsset">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{ElMessage,ElMessageBox}from'element-plus';import{onMounted,reactive,ref}from'vue';import{checkinHabit,healthTrend,listAssets,listContacts,listHabits,markContacted,revealAsset,saveAsset,saveContact,saveHabit}from'@/api/lifeManagement';const tab=ref('habit'),habits=ref<any[]>([]),contacts=ref<any[]>([]),assets=ref<any[]>([]),trend=ref<any>({}),habitVisible=ref(false),checkinVisible=ref(false),contactVisible=ref(false),assetVisible=ref(false),selectedHabit=ref<any>();const habit=reactive<any>({name:'',frequency:'DAILY',targetCount:1,metricType:'',targetValue:undefined,unit:'',active:true}),checkinForm=reactive<any>({checkinDate:new Date().toISOString().slice(0,10),value:undefined,note:'',source:'MANUAL'}),contact=reactive<any>({name:'',relationship:'',company:'',birthday:'',followUpAt:'',preferences:'',note:''}),asset=reactive<any>({assetType:'DEVICE',name:'',purchaseAmount:undefined,location:'',warrantyUntil:'',expiresAt:'',sensitive:false,sensitiveDetails:'',note:''});const assetTypes=['HOUSE','VEHICLE','DEVICE','VALUABLE','DOCUMENT','CONTRACT','INSURANCE'];async function load(){[habits.value,contacts.value,assets.value]=await Promise.all([listHabits().then(x=>x.data),listContacts().then(x=>x.data),listAssets().then(x=>x.data)]);}async function createHabit(){await saveHabit({...habit,metricType:habit.metricType||undefined});habitVisible.value=false;await load();}function checkin(x:any){selectedHabit.value=x;checkinForm.value=undefined;checkinVisible.value=true;}async function saveCheckin(){await checkinHabit(selectedHabit.value.id,checkinForm);checkinVisible.value=false;await load();}async function showTrend(metric:string){trend.value=(await healthTrend(metric)).data;}async function createContact(){await saveContact({...contact,birthday:contact.birthday||undefined,followUpAt:contact.followUpAt||undefined});contactVisible.value=false;await load();}async function contacted(x:any){await markContacted(x.id);await load();}async function createAsset(){await saveAsset({...asset,warrantyUntil:asset.warrantyUntil||undefined,expiresAt:asset.expiresAt||undefined});assetVisible.value=false;await load();}async function reveal(x:any){await ElMessageBox.confirm('敏感详情只应在私密环境查看。确认继续？','二次确认',{confirmButtonText:'确认查看',type:'warning'});ElMessageBox.alert((await revealAsset(x.id)).data||'无敏感详情','敏感详情');}onMounted(load);</script>
<style scoped>.page{display:flex;flex-direction:column;gap:14px}.toolbar{display:flex;justify-content:flex-end;margin-bottom:12px}.habit-grid,.asset-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.habit-grid article,.asset-grid article,.contact-cards article{padding:16px;border:1px solid #e4eaf2;border-radius:14px}.habit-grid article>div,.asset-grid article>div{display:flex;justify-content:space-between}.habit-grid strong{font-size:28px;color:#5275f5}.actions{display:flex;gap:8px;margin-top:12px}.trend{margin-top:14px}.trend div{display:flex;justify-content:space-between;padding:8px;border-bottom:1px solid #eee}.contact-cards{display:none}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:768px){.habit-grid,.asset-grid{grid-template-columns:1fr}.tabs :deep(.el-table){display:none}.contact-cards{display:flex;flex-direction:column;gap:10px}.contact-cards small{display:block;color:#718096}.two{grid-template-columns:1fr}}</style>
